 const pension=Math.max(0,Number(config.pension)||0),dependents=Math.min(30,Math.max(0,Math.floor(Number(config.dependents)||0))),legal=cents40(inss+dependents*PAYROLL_TABLE40.dependent+pension),deduction=Math.max(legal,PAYROLL_TABLE40.simplified),irBase=Math.max(0,cents40(gross-deduction)),bracket=PAYROLL_TABLE40.irrf.find(([ceiling])=>irBase<=ceiling),tax=cents40(Math.max(0,irBase*bracket[1]-bracket[2])),reduction=gross<=5000?Math.min(tax,312.89):gross<=7350?Math.min(tax,Math.max(0,cents40(978.62-.133145*gross))):0,irrf=cents40(Math.max(0,tax-reduction)),other=cents40((config.deductions||[]).reduce((sum,x)=>sum+Math.max(0,Number(x.amount)||0),0)),net=cents40(gross+nontaxable-inss-irrf-pension-other);
