function treeLinkMessage41(from,to){const t=triggerTreeState40(),ids=new Set(treeVisibleNodes40().map(n=>n.id));if(from===to||!ids.has(from)||!ids.has(to))return 'Escolha duas caixas diferentes.';if(t.edges.some(e=>e.from===from&&e.to===to))return 'Essas caixas já estão conectadas.';const pending=[to],seen=new Set();while(pending.length){const current=pending.pop();if(current===from)return 'Essa ligação voltaria ao início. Crie outro episódio.';if(seen.has(current))continue;seen.add(current);for(const e of t.edges)if(e.from===current)pending.push(e.to);}return '';}
function awardTreeLink41(from,to){normalize34();const t=triggerTreeState40(),a=t.nodes.find(n=>n.id===from),b=t.nodes.find(n=>n.id===to);if(!a||!b)return false;const signature=treeSignature42([a.type,a.title,b.type,b.title]);if(state.rewards34.ledger.some(r=>r.key==='tree-link42:'+signature||r.key.startsWith('tree-link41:')&&r.key.slice(r.key.indexOf(':',12)+1)===signature))return false;return grantReward34('tree-link42:'+signature,10,'Ligação: '+a.title+' → '+b.title,todayISO());}
