function addCareBox41(id){const goal=treeCareRows41().find(g=>g.id===id),t=triggerTreeState40();if(!goal)return false;const name=goal.label.trim().toLocaleLowerCase('pt-BR');if(t.nodes.some(n=>n.careGoal41===id||String(n.title||'').trim().toLocaleLowerCase('pt-BR')===name))return false;const index=t.nodes.length;t.nodes.push({id:cryptoId(),title:goal.label,type:'behavior',careGoal41:id,note:'Um tema que escolhi cuidar. Posso ligar uma situação antes e uma alternativa depois.',x:30+(index%4)*285,y:30+Math.floor(index/4)*210});awardTreeNode42(t.nodes[t.nodes.length-1]);return true;}
function renderCarePalette41(){const box=$('#carePalette41');if(!box)return;const nodes=treeVisibleNodes40();const rows=treeCareRows41();box.innerHTML='<header><div><strong>Caixas prontas dos meus cuidados</strong><p class="note">Adicione o tema e ligue uma situação antes e uma alternativa depois. Você escolhe as relações.</p></div><button type="button" class="ghost" data-care-all41>Adicionar todos</button></header><div>'+rows.map(g=>{const exists=nodes.some(n=>n.careGoal41===g.id||n.title?.trim().toLocaleLowerCase('pt-BR')===g.label.trim().toLocaleLowerCase('pt-BR'));return `<button type="button" class="ghost" data-care-box41="${g.id}" ${exists?'disabled':''}>${exists?'✓':'+'} ${escapeHTML(g.label)}</button>`}).join('')+'</div>'+(rows.length?'':'<p class="note">Escolha temas em “O que quero cuidar agora?”. Eles aparecerão aqui como caixas prontas.</p>');box.querySelectorAll('[data-care-box41]').forEach(b=>b.onclick=()=>{if(addCareBox41(b.dataset.careBox41)){saveState();renderTriggerTree40();}});box.querySelector('[data-care-all41]').disabled=!rows.length;box.querySelector('[data-care-all41]').onclick=()=>{let count=0;for(const g of rows)if(addCareBox41(g.id))count++;if(count){saveState();renderTriggerTree40();}else toast('Esses cuidados já estão no mapa.');};}
