  for(let i=0;i<2;i++){if(!treeLinkMessage41(nodes[i].id,nodes[i+1].id))treeConnect40(nodes[i].id,nodes[i+1].id);}
  saveState();renderTriggerTree40();renderTreeProgress42();drawXP36();
